 for(const p of rows){const k=apsCellKeyF(q,p.positionM,m),rangeGate=k.step,angleGate=apsRadF(APS_F.azimuthBeamDeg),priorMotion=APS_F.velocityGateMps*m.periodS*m.n,span=Math.ceil(priorMotion/k.step)+1;let best=null,score=Infinity;
  for(let dr=-span;dr<=span;dr++)for(let da=-1;da<=1;da++){const set=q.cellIndex.get((k.rb+dr)+':'+((k.ab+da+k.naz)%k.naz));if(!set)continue;for(const id of set){const c=q.cells.get(id);if(turn-c.lastTurn>=m.n)continue;const ck=apsCellKeyF(q,c.point,m),age=Math.max(0,p.measuredAtS-c.lastAtS),rg=rangeGate+APS_F.velocityGateMps*age,ag=angleGate+Math.atan2(APS_F.velocityGateMps*age,Math.max(1,k.r)),metric=((k.r-ck.r)/rg)**2+(apsAngleF(k.az-ck.az)/ag)**2;if(metric<=1&&metric<score){score=metric;best=c;}}}
  if(!best){if(q.cells.size>=APS_F.maxCandidates){q.stats.candidateDrops++;continue;}best={id:q.nextContact++,mask:0,lastTurn:turn,point:{...p.positionM},lastAtS:p.measuredAtS,confirmed:false};q.cells.set(best.id,best);}else apsIndexDeleteF(q,best);
  const shift=turn-best.lastTurn;best.mask=((best.mask<<Math.min(m.n,shift))|1)&nmask;best.lastTurn=turn;best.lastAtS=p.measuredAtS;best.point={...p.positionM};best.extent={rangeM:p.rangeExtentM,crossM:p.crossExtentM};apsIndexAddF(q,best,m);
  best.measurement={positionM:{...p.positionM},covarianceM2:[...p.covarianceM2],domainEvidence:{...p.domainEvidence},measuredAtS:p.measuredAtS};
  /* Confirmation is evaluated once the whole scan is complete, including a
     missed final look. It must not be conditional on detecting scan N. */

 }return out;
}

